style.css:
@-moz-document domain("roblox.com") {
/* ===== Wallpaper ===== */
    html,
    body,
    .rbx-body {
        background: url("https://media.discordapp.net/attachments/1492982401151013146/1533415153628876985/ChatGPT_Image_Aug_1_2026_01_17_31_AM.png?ex=6a711066&is=6a6fbee6&hm=316f3302d5e3acfbe938eb099f1b2d91048e0d28d60b5f4fb96ca786ddc6dca5&=&format=webp&quality=lossless&width=1423&height=800") center center / cover fixed no-repeat !important;
    }

    /* Remove Roblox's default background */
    body::before {
        display: none !important;
    }

    /* Main content */
    #container-main,
    .container-main,
    .content,
    .content-body,
    main {
        background: transparent !important;
    }

    /* Glass effect for panels */
    .section,
    .card,
    .content,
    .rbx-card,
    .catalog-item-container,
    .game-card-container,
    .profile-container,
    .home-container,
    .friends-list-container,
    .avatar-card-container,
    .chat-container,
    .game-card {
        background: rgba(20,20,20,.55) !important;
        backdrop-filter: blur(12px);
        -webkit-backdrop-filter: blur(12px);
        border-radius: 18px !important;
        border: 1px solid rgba(255,255,255,.08) !important;
    }

    /* Top navigation */
    .navbar,
    .navbar-fixed-top,
    .left-col {
        background: rgba(15,15,15,.65) !important;
        backdrop-filter: blur(14px);
        -webkit-backdrop-filter: blur(14px);
    }

    /* Buttons */
    .btn-primary {
        background: rgba(255,255,255,.15) !important;
        border: 1px solid rgba(255,255,255,.25) !important;
    }

    /* Footer */
    footer {
        background: transparent !important;
    }

    /* Remove extra backgrounds */
    * {
        box-shadow: none !important;
    }
}
